import { useState } from 'react';

export function VerticalTabs() {
  const tabs = {{tabs}};
  const [active, setActive] = useState(tabs[0].id);
  return (
    <div className="flex gap-6">
      <div className="w-48 flex flex-col">
        {tabs.map((t) => (
          <button key={t.id} onClick={() => setActive(t.id)}
            className={`text-left px-4 py-2 rounded ${active === t.id ? 'bg-blue-50 text-blue-700' : 'hover:bg-gray-50'}`}>
            {t.label}
          </button>
        ))}
      </div>
      <div className="flex-1">{tabs.find((t) => t.id === active)?.content}</div>
    </div>
  );
}
